262	    private Node<T> insert(Node<T> node, T value) {
263	        if (node == null) {
264	            size++;
265	            return new Node<>(value);
266	        }
267	
268	        int cmp = compare(value, node.value);
269	        if (cmp < 0) {
270	            node.left = insert(node.left, value);
271	        } else if (cmp > 0) {
272	            node.right = insert(node.right, value);
273	        } else {
274	            return node; // duplicate: no change
275	        }
276	
277	        updateHeight(node);
278	        return rebalance(node);
279	    }
