281	    private Node<T> remove(Node<T> node, T value) {
282	        if (node == null) {
283	            return null;
284	        }
285	
286	        int cmp = compare(value, node.value);
287	        if (cmp < 0) {
288	            node.left = remove(node.left, value);
289	        } else if (cmp > 0) {
290	            node.right = remove(node.right, value);
291	        } else if (node.left == null || node.right == null) {
292	            // Zero or one child: splice the node out.
293	            size--;
294	            node = (node.left != null) ? node.left : node.right;
295	        } else {
296	            // Two children: replace with in-order successor, then delete it.
297	            Node<T> successor = minNode(node.right);
298	            node.value = successor.value;
299	            node.right = remove(node.right, successor.value);
300	        }
301	
302	        if (node == null) {
303	            return null;
304	        }
305	        updateHeight(node);
306	        return rebalance(node);
307	    }
