316	    /** Restores the AVL invariant at {@code node} with at most two rotations. */
317	    private Node<T> rebalance(Node<T> node) {
318	        int balance = balanceFactor(node);
319	
320	        // Left-heavy
321	        if (balance > 1) {
322	            if (balanceFactor(node.left) < 0) {
323	                node.left = rotateLeft(node.left); // Left-Right case
324	            }
325	            return rotateRight(node); // Left-Left case
326	        }
327	
328	        // Right-heavy
329	        if (balance < -1) {
330	            if (balanceFactor(node.right) > 0) {
331	                node.right = rotateRight(node.right); // Right-Left case
332	            }
333	            return rotateLeft(node); // Right-Right case
334	        }
335	
336	        return node; // already balanced
337	    }
338	
339	    private Node<T> rotateRight(Node<T> y) {
340	        Node<T> x = y.left;
341	        y.left = x.right;
342	        x.right = y;
343	        updateHeight(y);
344	        updateHeight(x);
345	        return x;
346	    }
347	
348	    private Node<T> rotateLeft(Node<T> x) {
349	        Node<T> y = x.right;
350	        x.right = y.left;
351	        y.left = x;
352	        updateHeight(x);
353	        updateHeight(y);
354	        return y;
355	    }
