358	    // Traversals
359	    // ---------------------------------------------------------------------
360	
361	    private void inOrder(Node<T> node, List<T> out) {
362	        if (node != null) {
363	            inOrder(node.left, out);
364	            out.add(node.value);
365	            inOrder(node.right, out);
366	        }
367	    }
368	
369	    private void preOrder(Node<T> node, List<T> out) {
370	        if (node != null) {
371	            out.add(node.value);
372	            preOrder(node.left, out);
373	            preOrder(node.right, out);
374	        }
375	    }
