377	    // ---------------------------------------------------------------------
378	    // Height / balance helpers
379	    // ---------------------------------------------------------------------
380	
381	    private static int height(Node<?> node) {
382	        return node == null ? 0 : node.height;
383	    }
384	
385	    private static void updateHeight(Node<?> node) {
386	        node.height = 1 + Math.max(height(node.left), height(node.right));
387	    }
388	
389	    private static int balanceFactor(Node<?> node) {
390	        return node == null ? 0 : height(node.left) - height(node.right);
391	    }
392	
393	    /** Recursively checks ordering, height and balance; returns the node count. */
394	    private int validate(Node<T> node, T lowerExclusive, T upperExclusive) {
395	        if (node == null) {
396	            return 0;
397	        }
398	        if (lowerExclusive != null && compare(node.value, lowerExclusive) <= 0) {
399	            throw new IllegalStateException("BST order violated at " + node.value);
400	        }
401	        if (upperExclusive != null && compare(node.value, upperExclusive) >= 0) {
402	            throw new IllegalStateException("BST order violated at " + node.value);
403	        }
404	
405	        int leftCount = validate(node.left, lowerExclusive, node.value);
406	        int rightCount = validate(node.right, node.value, upperExclusive);
407	
408	        int expectedHeight = 1 + Math.max(height(node.left), height(node.right));
409	        if (node.height != expectedHeight) {
410	            throw new IllegalStateException("stale height at " + node.value
411	                    + ": stored " + node.height + " expected " + expectedHeight);
412	        }
413	        if (Math.abs(balanceFactor(node)) > 1) {
414	            throw new IllegalStateException("unbalanced at " + node.value
415	                    + " (balance " + balanceFactor(node) + ")");
416	        }
417	        return leftCount + rightCount + 1;
418	    }
419	
420	    @SuppressWarnings("unchecked")
421	    private int compare(T a, T b) {
422	        if (comparator != null) {
423	            return comparator.compare(a, b);
424	        }
425	        return ((Comparable<? super T>) a).compareTo(b);
426	    }
427	}
