429	/**
430	 * Demonstrates and self-tests the {@link AVLTree} API. Every operation is
431	 * checked with assertions and the tree's invariants are re-validated after each
432	 * mutation, so a clean run is evidence of correctness rather than something to
433	 * eyeball.
434	 */
435	class Main {
436	    public static void main(String[] args) {
437	        AVLTree<Integer> tree = new AVLTree<>();
438	        for (int key : new int[] {10, 20, 30, 40, 50, 25}) {
439	            tree.insert(key);
440	        }
441	        tree.validate();
442	
443	        // Preserves the original demo's pre-order output.
444	        System.out.println("pre-order : " + tree.preOrder());
445	        System.out.println("in-order  : " + tree.inOrder());
446	
447	        check(tree.preOrder().equals(List.of(30, 20, 10, 25, 40, 50)), "pre-order");
448	        check(tree.inOrder().equals(List.of(10, 20, 25, 30, 40, 50)), "sorted order");
449	        check(tree.size() == 6, "size");
450	        check(tree.height() == 3, "height");
451	        check(tree.contains(25) && !tree.contains(99), "contains");
452	        check(tree.min() == 10 && tree.max() == 50, "min/max");
453	        check(tree.floor(26).equals(Optional.of(25)), "floor");
454	        check(tree.ceiling(26).equals(Optional.of(30)), "ceiling");
455	        check(tree.floor(5).isEmpty() && tree.ceiling(99).isEmpty(), "out-of-range queries");
456	
457	        // Inserting a duplicate is a no-op; re-inserting after removal is not.
458	        check(!tree.insert(25), "duplicate insert reports no change");
459	        check(tree.remove(30) && !tree.remove(30), "remove reports change once");
460	        tree.validate();
461	        check(tree.inOrder().equals(List.of(10, 20, 25, 40, 50)), "order after remove");
462	        check(tree.size() == 5, "size after remove");
463	
464	        // Stress the balancing with a larger, adversarial (ascending) sequence.
465	        AVLTree<Integer> big = new AVLTree<>();
466	        for (int i = 1; i <= 1000; i++) {
467	            big.insert(i);
468	        }
469	        big.validate();
470	        check(big.height() <= 11, "balanced height for 1000 ascending inserts");
471	        for (int i = 1; i <= 1000; i += 2) {
472	            big.remove(i);
473	        }
474	        big.validate();
475	        check(big.size() == 500, "size after bulk removal");
476	
477	        System.out.println("all checks passed");
478	    }
479	
480	    private static void check(boolean condition, String what) {
481	        if (!condition) {
482	            throw new AssertionError("check failed: " + what);
483	        }
484	    }
485	}
